const item = $input.first();
const triggerData = $('Google Drive Trigger').item.json;
const apiConfig = $('Set: API Config').item.json;

const binaryProp = item.binary?.data;
if (!binaryProp || !binaryProp.data) {
  throw new Error('No binary PDF data received. Check the Google Drive Download node.');
}

if (apiConfig.anthropic_api_key.startsWith('YOUR_')) {
  throw new Error('Set your Anthropic API key in the Set: API Config node.');
}

return [{
  json: {
    claude_request: {
      model: apiConfig.model,
      max_tokens: 4096,
      temperature: 0,
      messages: [{
        role: 'user',
        content: [
          {
            type: 'document',
            source: {
              type: 'base64',
              media_type: 'application/pdf',
              data: binaryProp.data
            }
          },
          {
            type: 'text',
            text: 'Extract all text from this PDF document. Return only the raw text content, preserving paragraph breaks with blank lines. Do not summarize, analyze, or add commentary - return the exact text as written.'
          }
        ]
      }]
    },
    filename: triggerData.name,
    anthropic_api_key: apiConfig.anthropic_api_key,
    research_question: apiConfig.research_question,
    analysis_method: apiConfig.analysis_method,
    chunk_size_words: apiConfig.chunk_size_words,
    model: apiConfig.model
  }
}];

const apiResponse = $input.first().json;
const prepNode = $('Code: Prepare PDF for Claude').item.json;

if (!apiResponse.content || !apiResponse.content[0] || !apiResponse.content[0].text) {
  throw new Error('PDF extraction failed. API response: ' + JSON.stringify(apiResponse).substring(0, 300));
}

const extractedText = apiResponse.content[0].text.trim();

if (extractedText.length < 50) {
  throw new Error('Very little text extracted (' + extractedText.length + ' chars). The PDF may be image-based or scanned. Consider OCR pre-processing.');
}

return [{
  json: {
    extracted_text: extractedText,
    filename: prepNode.filename,
    extraction_method: 'claude_pdf',
    char_count: extractedText.length,
    research_question: prepNode.research_question,
    analysis_method: prepNode.analysis_method,
    chunk_size_words: prepNode.chunk_size_words,
    model: prepNode.model,
    anthropic_api_key: prepNode.anthropic_api_key
  }
}];

const item = $input.first().json;
const triggerData = $('Google Drive Trigger').item.json;
const apiConfig = $('Set: API Config').item.json;

const rawText = item.text || item.data || '';

if (!rawText || rawText.trim().length < 20) {
  throw new Error('Insufficient text extracted from Word document. File may be empty or in an unsupported format.');
}

return [{
  json: {
    extracted_text: rawText.trim(),
    filename: triggerData.name,
    extraction_method: 'n8n_extract',
    char_count: rawText.length,
    research_question: apiConfig.research_question,
    analysis_method: apiConfig.analysis_method,
    chunk_size_words: apiConfig.chunk_size_words,
    model: apiConfig.model,
    anthropic_api_key: apiConfig.anthropic_api_key
  }
}];

const data = $input.first().json;

if (!data.extracted_text || data.extracted_text.trim().length === 0) {
  throw new Error('No extracted text available. Check the PDF or DOCX extraction nodes.');
}
if (!data.anthropic_api_key || data.anthropic_api_key.startsWith('YOUR_')) {
  throw new Error('Set your Anthropic API key in the Set: API Config node.');
}

const text = data.extracted_text.trim();
const chunkSizeWords = parseInt(data.chunk_size_words) || 800;
const overlap = 50;
const words = text.split(/\s+/).filter(w => w.length > 0);

if (words.length === 0) {
  throw new Error('Text contains no words after cleaning.');
}

const chunks = [];
for (let i = 0; i < words.length; i += (chunkSizeWords - overlap)) {
  const end = Math.min(i + chunkSizeWords, words.length);
  chunks.push(words.slice(i, end).join(' '));
  if (end >= words.length) break;
}

return chunks.map((chunk, idx) => ({
  json: {
    chunk_text: chunk,
    chunk_index: idx,
    total_chunks: chunks.length,
    word_count: chunk.split(/\s+/).length,
    research_question: data.research_question,
    analysis_method: data.analysis_method,
    source_name: data.filename,
    extraction_method: data.extraction_method,
    model: data.model,
    anthropic_api_key: data.anthropic_api_key,
    started_at: new Date().toISOString()
  }
}));

const apiResponse = $input.first().json;
const buildNode = $('Code: Build Open Coding Request').item.json;

let codes = [];
const parseErrors = [];

try {
  if (!apiResponse.content || !apiResponse.content[0] || !apiResponse.content[0].text) {
    throw new Error('Unexpected API response: ' + JSON.stringify(apiResponse).substring(0, 300));
  }

  let raw = apiResponse.content[0].text.trim();
  raw = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  raw = raw.replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

  const parsed = JSON.parse(raw);

  if (!parsed.codes || !Array.isArray(parsed.codes)) {
    throw new Error('Response missing codes array. Got: ' + raw.substring(0, 200));
  }

  codes = parsed.codes
    .filter(c => c.code && c.evidence)
    .map(c => ({
      code: String(c.code).trim(),
      description: String(c.description || '').trim(),
      evidence: String(c.evidence).trim(),
      memo: String(c.memo || '').trim(),
      chunk_index: buildNode.chunk_index,
      source_name: buildNode.source_name
    }));

} catch (e) {
  parseErrors.push({
    stage: 'open_coding',
    chunk_index: buildNode.chunk_index,
    error: e.message,
    raw_response: apiResponse.content ? apiResponse.content[0].text.substring(0, 500) : 'no content'
  });
}

return [{
  json: {
    codes: codes,
    parse_errors: parseErrors,
    chunk_index: buildNode.chunk_index,
    total_chunks: buildNode.total_chunks,
    tokens_used: apiResponse.usage ? (apiResponse.usage.input_tokens + apiResponse.usage.output_tokens) : 0,
    research_question: buildNode.research_question,
    analysis_method: buildNode.analysis_method,
    source_name: buildNode.source_name,
    model: buildNode.model,
    anthropic_api_key: buildNode.anthropic_api_key
  }
}];

const allItems = $input.all();
const allCodes = [];
const allErrors = [];
let totalTokens = 0;

for (const item of allItems) {
  allCodes.push(...(item.json.codes || []));
  allErrors.push(...(item.json.parse_errors || []));
  totalTokens += item.json.tokens_used || 0;
}

const meta = allItems[0].json;

return [{
  json: {
    all_codes: allCodes,
    total_codes: allCodes.length,
    parse_errors: allErrors,
    total_tokens_used: totalTokens,
    research_question: meta.research_question,
    analysis_method: meta.analysis_method,
    source_name: meta.source_name,
    model: meta.model,
    anthropic_api_key: meta.anthropic_api_key,
    coding_completed_at: new Date().toISOString()
  }
}];

const apiResponse = $input.first().json;
const buildNode = $('Code: Build Synthesis Request').item.json;

let themes = [];
let summary = '';
let researcherNotes = '';
const errors = [...(buildNode.parse_errors || [])];

try {
  if (!apiResponse.content || !apiResponse.content[0] || !apiResponse.content[0].text) {
    throw new Error('Unexpected synthesis response: ' + JSON.stringify(apiResponse).substring(0, 300));
  }

  let raw = apiResponse.content[0].text.trim();
  raw = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  raw = raw.replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

  const parsed = JSON.parse(raw);

  if (!parsed.themes || !Array.isArray(parsed.themes)) {
    throw new Error('Response missing themes array. Got: ' + raw.substring(0, 200));
  }

  themes = parsed.themes.map(t => ({
    theme_name: t.theme_name || 'Unnamed Theme',
    theme_description: t.theme_description || '',
    sub_themes: Array.isArray(t.sub_themes) ? t.sub_themes : [],
    supporting_codes: Array.isArray(t.supporting_codes) ? t.supporting_codes : [],
    evidence_snippets: Array.isArray(t.evidence_snippets) ? t.evidence_snippets : [],
    frequency: typeof t.frequency === 'number' ? t.frequency : (t.supporting_codes ? t.supporting_codes.length : 0),
    analytical_memo: t.analytical_memo || ''
  }));

  summary = parsed.overall_summary || '';
  researcherNotes = parsed.researcher_notes || '';

} catch (e) {
  errors.push({ stage: 'theme_synthesis', error: e.message });
}

const synthesisTokens = apiResponse.usage
  ? (apiResponse.usage.input_tokens + apiResponse.usage.output_tokens)
  : 0;

return [{
  json: {
    metadata: {
      source_name: buildNode.source_name,
      research_question: buildNode.research_question,
      analysis_method: buildNode.analysis_method,
      model_used: buildNode.model,
      coding_completed_at: buildNode.coding_completed_at,
      synthesis_completed_at: new Date().toISOString(),
      total_codes_analyzed: buildNode.total_codes,
      total_themes_identified: themes.length,
      total_tokens_used: (buildNode.total_tokens_used || 0) + synthesisTokens
    },
    summary: summary,
    researcher_notes: researcherNotes,
    themes: themes,
    raw_codes: buildNode.all_codes,
    errors: errors
  }
}];
